import React, { useRef } from 'react';
import { View, StyleSheet, PanResponder, Animated, Text } from 'react-native';

export interface DockItemData {
  title: string;
  active?: boolean;
}

export interface FloatingDockProps {
  items: DockItemData[];
  baseSize?: number;
  maxMagnification?: number;
  influenceRadius?: number;
}

export const FloatingDock: React.FC<FloatingDockProps> = ({
  items,
  baseSize = 36,
  maxMagnification = 0.75,
  influenceRadius = 60,
}) => {
  const scales = useRef(items.map(() => new Animated.Value(1.0))).current;
  const containerRef = useRef<View>(null);
  const containerX = useRef<number>(0);

  const updateScales = (touchX: number) => {
    items.forEach((_, idx) => {
      const itemCenter = containerX.current + 12 + idx * (baseSize + 10) + baseSize / 2;
      const distance = Math.abs(touchX - itemCenter);
      let targetScale = 1.0;
      if (influenceRadius > 0 && distance < influenceRadius) {
        const factor = Math.cos((distance / influenceRadius) * (Math.PI / 2));
        targetScale = 1.0 + maxMagnification * factor * factor;
      }
      Animated.spring(scales[idx], {
        toValue: targetScale,
        friction: 7,
        tension: 120,
        useNativeDriver: true,
      }).start();
    });
  };

  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onPanResponderGrant: (evt) => {
        updateScales(evt.nativeEvent.pageX);
      },
      onPanResponderMove: (evt) => {
        updateScales(evt.nativeEvent.pageX);
      },
      onPanResponderRelease: () => {
        items.forEach((_, idx) => {
          Animated.spring(scales[idx], {
            toValue: 1.0,
            friction: 7,
            tension: 50,
            useNativeDriver: true,
          }).start();
        });
      },
    })
  ).current;

  return (
    <View
      ref={containerRef}
      onLayout={() => {
        containerRef.current?.measure((_x, _y, _width, _height, pageX) => {
          containerX.current = pageX;
        });
      }}
      style={styles.dockContainer}
      {...panResponder.panHandlers}
    >
      {items.map((item, idx) => (
        <Animated.View
          key={item.title}
          style={[
            styles.dockItem,
            {
              width: baseSize,
              height: baseSize,
              transform: [{ scale: scales[idx] }],
            },
          ]}
        >
          <Text style={styles.iconText}>{item.title.slice(0, 2).toUpperCase()}</Text>
          {item.active && <View style={styles.activeDot} />}
        </Animated.View>
      ))}
    </View>
  );
};

const styles = StyleSheet.create({
  dockContainer: {
    flexDirection: 'row',
    alignItems: 'flex-end',
    backgroundColor: 'rgba(23, 23, 23, 0.75)',
    borderRadius: 24,
    paddingHorizontal: 12,
    paddingVertical: 10,
    gap: 10,
    borderWidth: 1,
    borderColor: 'rgba(255, 255, 255, 0.15)',
  },
  dockItem: {
    borderRadius: 16,
    backgroundColor: 'rgba(255, 255, 255, 0.1)',
    alignItems: 'center',
    justifyContent: 'center',
  },
  iconText: {
    color: '#fff',
    fontSize: 12,
    fontWeight: 'bold',
  },
  activeDot: {
    position: 'absolute',
    bottom: 2,
    width: 4,
    height: 4,
    borderRadius: 2,
    backgroundColor: '#e5e5e5',
  },
});

